{ echo '<div class="cover"><p style="color:#0b7f78;font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:9.5pt">Intelligence artificielle et transformation numérique en GRH</p><h1>Jour 5 • Scripts du formateur</h1><p class="intro">Un script d’environ 500 mots par page du fascicule (40 pages). Les indications en italique orange sont des consignes d’animation : questions à la salle, démonstrations, transitions. Le texte est rédigé pour être dit à l’oral et peut être adapté librement.</p><p class="intro"><b>Repères de temps :</b> chaque thématique dure 1 h 30 (cours 50 min, activité individuelle 30 min, quiz et correction 10 min). Un script se dit en 4 à 6 minutes environ.</p><p class="intro"><b>Lectures :</b> E = Eubanks, <i>Artificial Intelligence for HR</i> (2022), ch. 6 et 7 • H = Strohmeier (dir.), <i>Handbook of Research on AI in HRM</i> (2022), ch. 2, 4, 5, 12 et 13.</p></div>'; cat s1.html s2.html s3.html s4.html; } > scripts.html
